<?php
if(!defined('ABSPATH'))exit;
class XDN_AI_Admin_V2{
 public static function init(){add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_init',[__CLASS__,'register']);add_action('admin_enqueue_scripts',function($h){if(strpos($h,'xdn-ai')!==false)wp_enqueue_media();});add_action('wp_ajax_xdn_ai_research',[__CLASS__,'research']);add_action('wp_ajax_xdn_ai_watermark_all',[__CLASS__,'watermark']);}
 private static function s(){return get_option('xdn_ai_settings',[]);}
 public static function register(){register_setting('xdn_ai_settings_v2','xdn_ai_settings',[__CLASS__,'sanitize']);}
 public static function sanitize($in){$old=self::s();$o=$old;foreach(['openai_key','gemini_key'] as $k)$o[$k]=!empty($in[$k])?sanitize_text_field($in[$k]):($old[$k]??'');$o['openai_model']=sanitize_text_field($in['openai_model']??'gpt-5.6-luna');$o['gemini_model']=sanitize_text_field($in['gemini_model']??'gemini-3.6-flash');$o['seed_topic']=sanitize_text_field($in['seed_topic']??'xe đạp Ninh Bình');$o['auto_research']=!empty($in['auto_research'])?1:0;$o['auto_publish']=!empty($in['auto_publish'])?1:0;$o['publish_mode']=($in['publish_mode']??'draft')==='publish'?'publish':'draft';$o['posts_per_week']=max(1,min(7,(int)($in['posts_per_week']??7)));$o['watermark_enabled']=!empty($in['watermark_enabled'])?1:0;$o['logo_id']=absint($in['logo_id']??0);$o['logo_position']=sanitize_key($in['logo_position']??'bottom-right');$o['logo_size']=max(5,min(30,(float)($in['logo_size']??12)));$o['logo_opacity']=max(0,min(100,(int)($in['logo_opacity']??85)));$o['logo_margin']=max(1,min(10,(float)($in['logo_margin']??2)));$o['source_urls']=array_values(array_filter(array_map('esc_url_raw',preg_split('/\r\n|\r|\n/',(string)($in['source_urls']??'')))));$o['topic_pool']=array_values(array_filter(array_map('sanitize_text_field',preg_split('/\r\n|\r|\n/',(string)($in['topic_pool']??''))));$o['schedule']=[];for($d=1;$d<=7;$d++)$o['schedule'][$d]=['enabled'=>!empty($in['schedule'][$d]['enabled'])?1:0,'time'=>preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$in['schedule'][$d]['time']??'09:00')?$in['schedule'][$d]['time']:'09:00','topic'=>sanitize_text_field($in['schedule'][$d]['topic']??'')];return $o;}
 public static function menu(){add_menu_page('XDN AI Content','XDN AI Content','manage_options','xdn-ai-content',[__CLASS__,'dashboard'],'dashicons-edit-page',58);add_submenu_page('xdn-ai-content','Lịch đăng 7 bài/tuần','Lịch đăng','manage_options','xdn-ai-schedule',[__CLASS__,'schedule']);add_submenu_page('xdn-ai-content','Nghiên cứu từ khóa','Từ khóa SEO','manage_options','xdn-ai-keywords',[__CLASS__,'keywords']);add_submenu_page('xdn-ai-content','Content Planner','Content Planner','manage_options','xdn-ai-planner-v2',[__CLASS__,'planner']);add_submenu_page('xdn-ai-content','Cài đặt','Cài đặt','manage_options','xdn-ai-settings-v2',[__CLASS__,'settings']);}
 private static function box($a,$b){echo '<div style="background:#fff;border:1px solid #ddd;padding:18px;min-width:190px"><b>'.esc_html($a).'</b><div style="font-size:18px;margin-top:8px">'.esc_html($b).'</div></div>';}
 public static function dashboard(){$s=self::s();echo '<div class="wrap"><h1>🚲 XDN AI Content Engine 0.2.2</h1><p>Lịch 7 bài/tuần • nghiên cứu từ khóa • nguồn tham khảo • ảnh minh họa • logo.</p><div style="display:flex;gap:12px;flex-wrap:wrap">';self::box('Mục tiêu tuần',(int)($s['posts_per_week']??7).' bài');self::box('Bài gần nhất',(int)get_option('xdn_ai_last_post_id',0));self::box('Nghiên cứu gần nhất',get_option('xdn_ai_last_research_at','Chưa có'));echo '</div><p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=xdn-ai-schedule')).'">📅 Lịch đăng</a> <a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=xdn-ai-keywords')).'">🔎 Nghiên cứu từ khóa</a> <a class="button" href="'.esc_url(admin_url('admin.php?page=xdn-ai-planner-v2')).'">📝 Content Planner</a></p></div>';}
 public static function schedule(){$s=self::s();$sc=!empty($s['schedule'])?$s['schedule']:XDN_AI_Content_Engine::default_schedule();$names=[1=>'Thứ 2',2=>'Thứ 3',3=>'Thứ 4',4=>'Thứ 5',5=>'Thứ 6',6=>'Thứ 7',7=>'Chủ nhật'];echo '<div class="wrap"><h1>📅 Lịch đăng 7 bài/tuần</h1><p>Mỗi dòng là một slot. Hệ thống kiểm tra mỗi giờ và chỉ tạo tối đa số bài đã đặt trong tuần.</p><form method="post" action="options.php">';settings_fields('xdn_ai_settings_v2');echo '<table class="widefat striped"><tr><th>Ngày</th><th>Bật</th><th>Giờ</th><th>Chủ đề cố định</th></tr>';foreach($names as $d=>$n){$x=$sc[$d]??['enabled'=>1,'time'=>'09:00','topic'=>''];echo '<tr><td><b>'.$n.'</b></td><td><input type="checkbox" name="xdn_ai_settings[schedule]['.$d.'][enabled]" value="1" '.checked(!empty($x['enabled']),true,false).'></td><td><input type="time" name="xdn_ai_settings[schedule]['.$d.'][time]" value="'.esc_attr($x['time']).'"></td><td><input class="regular-text" name="xdn_ai_settings[schedule]['.$d.'][topic]" value="'.esc_attr($x['topic']??'').'" placeholder="Để trống = tự chọn"></td></tr>';}echo '</table><p><input type="number" min="1" max="7" name="xdn_ai_settings[posts_per_week]" value="'.esc_attr($s['posts_per_week']??7).'"> bài tối đa/tuần &nbsp; <label><input type="checkbox" name="xdn_ai_settings[auto_publish]" value="1" '.checked(!empty($s['auto_publish']),true,false).'> Bật lịch tự động</label></p>';submit_button('Lưu lịch');echo '</form></div>';}
 public static function keywords(){$s=self::s();$nonce=wp_create_nonce('xdn_ai_nonce');echo '<div class="wrap"><h1>🔎 Nghiên cứu từ khóa SEO</h1><p>Gemini phân tích keyword, search intent, content gap, câu hỏi và tiêu đề.</p><p><input id="xdn-v2-topic" class="regular-text" value="'.esc_attr($s['seed_topic']??'xe đạp Ninh Bình').'"> <button id="xdn-v2-go" class="button button-primary">Nghiên cứu</button> <span id="xdn-v2-status"></span></p><div id="xdn-v2-result"></div><script>(function(){var b=document.getElementById("xdn-v2-go");b.onclick=function(){b.disabled=true;var f=new FormData();f.append("action","xdn_ai_research");f.append("nonce","'.$nonce.'");f.append("topic",document.getElementById("xdn-v2-topic").value);document.getElementById("xdn-v2-status").textContent=" Đang nghiên cứu...";fetch("'.esc_url(admin_url('admin-ajax.php')).'",{method:"POST",body:f}).then(r=>r.json()).then(j=>{b.disabled=false;if(!j.success){document.getElementById("xdn-v2-status").textContent=" Lỗi: "+j.data;return;}document.getElementById("xdn-v2-status").textContent=" Hoàn tất";var h="<h2>Từ khóa cơ hội</h2><table class=\"widefat striped\"><tr><th>Keyword</th><th>Intent</th><th>Ưu tiên</th><th>Lý do</th></tr>";(j.data.keyword_opportunities||[]).forEach(function(x){h+="<tr><td>"+(x.keyword||"")+"</td><td>"+(x.intent||"")+"</td><td>"+(x.priority||"")+"</td><td>"+(x.reason||"")+"</td></tr>"});h+="</table><h2>Content gap</h2><ul>";(j.data.content_gaps||[]).forEach(function(x){h+="<li>"+x+"</li>"});h+="</ul><h2>Câu hỏi</h2><ul>";(j.data.questions||[]).forEach(function(x){h+="<li>"+x+"</li>"});h+="</ul><h2>Tiêu đề</h2><ol>";(j.data.recommended_titles||[]).forEach(function(x){h+="<li>"+x+"</li>"});h+="</ol>";document.getElementById("xdn-v2-result").innerHTML=h;});};})();</script></div>';}
 public static function planner(){$s=self::s();$topics=!empty($s['topic_pool'])?$s['topic_pool']:XDN_AI_Content_Engine::default_topics();echo '<div class="wrap"><h1>📝 Content Planner</h1><table class="widefat striped"><tr><th>#</th><th>Chủ đề</th><th>Nhóm</th></tr>';foreach($topics as $i=>$t){$g=stripos($t,'sửa')!==false||stripos($t,'bảo dưỡng')!==false?'Sửa chữa/Bảo dưỡng':(stripos($t,'Ninh Bình')!==false?'Local SEO':(stripos($t,'chọn')!==false||stripos($t,'mua')!==false?'Tư vấn':'Kiến thức'));echo '<tr><td>'.($i+1).'</td><td>'.esc_html($t).'</td><td>'.esc_html($g).'</td></tr>';}echo '</table></div>';}
 public static function settings(){$s=self::s();$logo=(int)($s['logo_id']??0);echo '<div class="wrap"><h1>⚙ Cài đặt XDN AI</h1><form method="post" action="options.php">';settings_fields('xdn_ai_settings_v2');echo '<table class="form-table">';self::row('OpenAI API Key','<input type="password" class="regular-text" name="xdn_ai_settings[openai_key]" placeholder="Giữ trống để giữ key"> Đã lưu: '.(!empty($s['openai_key'])?'Có':'Chưa có'));self::row('OpenAI Model','<input class="regular-text" name="xdn_ai_settings[openai_model]" value="'.esc_attr($s['openai_model']??'gpt-5.6-luna').'">');self::row('Gemini API Key','<input type="password" class="regular-text" name="xdn_ai_settings[gemini_key]" placeholder="Giữ trống để giữ key"> Đã lưu: '.(!empty($s['gemini_key'])?'Có':'Chưa có'));self::row('Gemini Model','<input class="regular-text" name="xdn_ai_settings[gemini_model]" value="'.esc_attr($s['gemini_model']??'gemini-3.6-flash').'">');self::row('Chủ đề gốc','<input class="regular-text" name="xdn_ai_settings[seed_topic]" value="'.esc_attr($s['seed_topic']??'xe đạp Ninh Bình').'">');self::row('Tự nghiên cứu','<label><input type="checkbox" name="xdn_ai_settings[auto_research]" value="1" '.checked(!empty($s['auto_research']),true,false).'> Gemini tự nghiên cứu</label>');self::row('Nguồn tham khảo','<textarea class="large-text" rows="5" name="xdn_ai_settings[source_urls]">'.esc_textarea(implode("\n",$s['source_urls']??[])).'</textarea>');self::row('Kho chủ đề','<textarea class="large-text" rows="8" name="xdn_ai_settings[topic_pool]">'.esc_textarea(implode("\n",$s['topic_pool']??XDN_AI_Content_Engine::default_topics())).'</textarea>');self::row('Logo','<input type="hidden" id="xdn-v2-logo" name="xdn_ai_settings[logo_id]" value="'.$logo.'"><button type="button" class="button" id="xdn-v2-logo-btn">Chọn logo Media Library</button>');self::row('Watermark','<label><input type="checkbox" name="xdn_ai_settings[watermark_enabled]" value="1" '.checked(!empty($s['watermark_enabled']),true,false).'> Đóng logo ảnh mới và ảnh sản phẩm</label>');echo '</table>';submit_button('Lưu cài đặt');echo '</form><hr><button class="button button-primary" id="xdn-v2-watermark">🖼️ Đóng logo ảnh cũ</button><span id="xdn-v2-ws"></span><script>(function(){var b=document.getElementById("xdn-v2-logo-btn");if(b)b.onclick=function(){var m=wp.media({title:"Chọn logo",button:{text:"Dùng logo"},multiple:false,library:{type:"image"}});m.on("select",function(){document.getElementById("xdn-v2-logo").value=m.state().get("selection").first().toJSON().id;});m.open()};var w=document.getElementById("xdn-v2-watermark");if(w)w.onclick=function(){var f=new FormData();f.append("action","xdn_ai_watermark_all");f.append("nonce","'.wp_create_nonce('xdn_ai_nonce').' ");fetch("'.esc_url(admin_url('admin-ajax.php')).'",{method:"POST",body:f}).then(r=>r.json()).then(j=>document.getElementById("xdn-v2-ws").textContent=j.success?" Đã xử lý "+j.data+" ảnh.":" Lỗi: "+j.data)};})();</script></div>';}
 private static function row($a,$b){echo '<tr><th>'.esc_html($a).'</th><td>'.$b.'</td></tr>';}
 public static function research(){if(!current_user_can('manage_options')||!check_ajax_referer('xdn_ai_nonce','nonce',false))wp_send_json_error('Không có quyền.');$t=sanitize_text_field(wp_unslash($_POST['topic']??''));$r=XDN_AI_Gemini::research($t,self::s());if(is_wp_error($r))wp_send_json_error($r->get_error_message());update_option('xdn_ai_last_research',$r,false);update_option('xdn_ai_last_research_at',current_time('mysql'),false);wp_send_json_success($r);}
 public static function watermark(){if(!current_user_can('manage_options')||!check_ajax_referer('xdn_ai_nonce','nonce',false))wp_send_json_error('Không có quyền.');wp_send_json_success(XDN_AI_Image::process_existing_images());}
}